  async function markRead(customerId?: string) { if (!customerId) return; try { await fetch('/api/sms/read', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ customerId }) }) } catch { /* ignore */ } loadUnread() }
  async function dismissUnmatched(phone?: string | null) { if (!phone) return; try { await fetch('/api/sms/read', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ phone }) }) } catch { /* ignore */ } loadUnread() }
  function openInboxItem(item: { customer_id: string | null; customer_name: string; unmatched: boolean; phone: string | null; order_id?: string | null; order_number?: string | null }) { if (item.unmatched) { setStatus(`Reply from ${item.phone || 'an unknown number'} — this customer isn't imported into the dashboard yet.`); return } const order = orders.find((o) => o.customer_id === item.customer_id); if (order) { openConvo(order); return } if (item.order_id) { openConvo({ id: item.order_id, order_number: item.order_number || '', customer_id: item.customer_id, customers: { name: item.customer_name, phone: item.phone } } as unknown as Order); return } setStatus(`Reply from ${item.customer_name} — no order on file to open.`) }
  function applyConvoTemplate(id: string) { setConvoTemplateId(id); const t = smsTemplates.find((x) => x.id === id); if (t) setConvoText(t.template_text) }
  async function sendConvo() { if (!convoOrder) return; if (!convoText.trim()) return setStatus('Message is blank.'); setConvoSending(true); try { const r = await fetch('/api/sms', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ templateText: convoText, audience: 'Both', orderIds: [convoOrder.id], resend: true, templateId: convoTemplateId || undefined, sentByEmail: currentEmail() || undefined }) }); const j = await r.json(); if (!r.ok) { setStatus(j.error || 'SMS sending failed'); return } if (!j.sent) { setStatus('Message not sent — check the mobile number.'); return } setConvoText(''); setConvoTemplateId(''); await loadConvo(convoOrder.id); await loadOrders() } catch { setStatus('SMS sending failed') } finally { setConvoSending(false) } }
  async function makeStripeLinks() { if (!selected.length) return setStatus('Select at least one order to create Stripe links.'); setStatus('Creating Stripe links…'); try { const r = await fetch('/api/stripe-links', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ orderIds: selected }) }); const j = await r.json(); if (!r.ok) return setStatus(j.error || 'Stripe link creation failed'); await loadOrders(); setStatus(`Stripe links: ${j.created} created, ${j.reused} reused — ${j.eligible} of ${j.selected} selected had a balance.`) } catch { setStatus('Stripe link creation failed') } }
  async function toggleReady(order: Order) { const ready = readyStatus(order) !== 'Ready'; setOrders((current) => current.map((o) => o.id === order.id ? { ...o, ready_status: ready ? 'Ready' : 'Not Ready' } : o)); const r = await fetch('/api/mark-ready', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ids: [order.id], ready }) }); const j = await r.json().catch(() => ({})); if (!r.ok) return setStatus(j.error || 'Prep status update failed'); setStatus(ready ? 'Marked prepped' : 'Marked not prepped') }
