  async function addItem(order: Order) { const r = await fetch('/api/order-items', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ order_id: order.id, quantity: 1, product_code: '', product_name: 'New product line', cubic_meters: 0, notes: '' }) }); const j = await r.json(); if (!r.ok || !j.item) return setStatus(j.error || 'Could not add line'); updateOrderItems(order.id, (items) => [...items, j.item]); setStatus('Line added') }
