  async function commitDelete(item: OrderItem) { const r = await fetch('/api/order-items', { method: 'DELETE', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ id: item.id }) }); const j = await r.json().catch(() => ({})); if (!r.ok) setStatus(j.error || 'Line delete failed') }
  function flushPendingDelete() { if (undoTimer.current) { clearTimeout(undoTimer.current); undoTimer.current = null } const pending = pendingDelete.current; pendingDelete.current = null; setUndoToast(null); if (pending) commitDelete(pending.item) }
  function deleteItem(orderId: string, item: OrderItem) { flushPendingDelete(); const items = orders.find((o) => o.id === orderId)?.items || []; const index = Math.max(items.findIndex((it) => it.id === item.id), 0); updateOrderItems(orderId, (current) => current.filter((it) => it.id !== item.id)); pendingDelete.current = { orderId, item, index }; setUndoToast({ orderId, item, index }); undoTimer.current = setTimeout(flushPendingDelete, 5000) }
  function undoDelete() { if (undoTimer.current) { clearTimeout(undoTimer.current); undoTimer.current = null } const pending = pendingDelete.current; pendingDelete.current = null; setUndoToast(null); if (!pending) return; updateOrderItems(pending.orderId, (current) => { const next = [...current]; next.splice(Math.min(pending.index, next.length), 0, pending.item); return next }); setStatus('Delete undone') }
  function openWodely() { if (!selected.length) return setStatus('Select at least one order to push to Wodely.'); setShowWodely(true) }
  async function pushWodely() { if (pushing || !selected.length) return; const ids = [...selected]; setPushing(true); setStatus('Pushing to Wodely…'); try { const r = await fetch('/api/wodely/push', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ids }) }); const j = await r.json(); if (!r.ok) { setStatus(j.error || 'Wodely push failed'); return } const archivedIds: string[] = Array.isArray(j.archivedIds) ? j.archivedIds : []; if (archivedIds.length) { setOrders((cur) => cur.filter((o) => !archivedIds.includes(o.id))); setExpanded((cur) => cur.filter((id) => !archivedIds.includes(id))) } setSelected([]); setShowWodely(false); setStatus(`Wodely: ${j.created} created, ${j.skipped} skipped, ${j.failed} failed${j.archived ? ` — ${j.archived} archived` : ''}.`) } catch { setStatus('Wodely push failed') } finally { setPushing(false) } }
