  function printCustomerLabels(mode: 'order' | 'item') { const chosen = orders.filter((order) => selected.includes(order.id)); if (!chosen.length) return setStatus('Select at least one order to print labels.'); const pages: { order_number: string; customer: string; note: string; footer: string; logo: string }[] = []; for (const order of chosen) { const c = customerOf(order); const customer = c?.name || ''; const orderNote = String(order.order_notes || '').trim(); const brandLogo = order.source === 'transforma' ? '/transforma-logo.png' : '/BoConcept-Logo.svg'; if (mode === 'item') { const expanded = (order.items || []).flatMap((item) => Array.from({ length: Math.max(1, Number(item.quantity || 1)) }, () => item)); const total = expanded.length || 1; if (!expanded.length) { pages.push({ order_number: order.order_number, customer, note: orderNote, footer: `1 of ${total}`, logo: brandLogo }) } else { expanded.forEach((item, i) => pages.push({ order_number: order.order_number, customer, note: [String(item.notes || '').trim(), orderNote].filter(Boolean).join('\n'), footer: `${i + 1} of ${total}`, logo: brandLogo })) } } else { pages.push({ order_number: order.order_number, customer, note: orderNote, footer: '______ of ______', logo: brandLogo }) } } const html = `<!doctype html><html><head><title>Customer Labels</title><style>@page{size:A4 landscape;margin:0}body{margin:0;font-family:Arial}.label{width:297mm;height:210mm;page-break-after:always;display:flex;align-items:center;justify-content:center;padding:12mm;box-sizing:border-box}.frame{width:100%;height:100%;border:3px solid #111;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.brand{margin-bottom:12mm}.brand img{width:38mm;height:auto}.order{font-size:56px;font-weight:800;margin-bottom:8mm}.customer{font-size:68px;font-weight:800}.notes{font-size:30px;font-weight:500;color:#222;margin-top:10mm;max-width:240mm;white-space:pre-wrap}.count{font-size:64px;font-weight:800;margin-top:14mm;letter-spacing:2px}</style></head><body>${pages.map((p) => `<section class="label"><div class="frame"><div class="brand"><img src="${p.logo}" alt="" /></div><div class="order">${escapeHtml(p.order_number)}</div><div class="customer">${escapeHtml(p.customer)}</div>${p.note ? `<div class="notes">${escapeHtml(p.note)}</div>` : ''}<div class="count">${escapeHtml(p.footer)}</div></div></section>`).join('')}</body></html>`; const win = window.open('', '_blank'); if (!win) return setStatus('Pop-up blocked — allow pop-ups to print labels.'); win.document.write(html); win.document.close(); setShowLabelModal(false); setTimeout(() => win.print(), 300) }
  function downloadCsv() { const headers = ['Order', 'Customer', 'Mobile', 'Payment Due', 'Payment', 'Prep Status', 'Customer Status', 'Street', 'Suburb', 'State', 'Postcode', 'ETA Shipment', 'Ready for Carrier', 'Delivery Date']; const rows = [headers.join(',')]; for (const order of visible) { const c = customerOf(order); rows.push([order.order_number, c?.name || '', c?.phone || '', order.payment_due, paymentStatus(order), readyStatus(order), order.order_status, c?.street_address || c?.address || '', c?.suburb || '', c?.state || '', c?.postcode || '', dateOnly(order.goods_in_date), dateOnly(order.goods_ready_date), dateOnly(order.delivery_date)].map(csv).join(',')) } const blob = new Blob([rows.join('\n')], { type: 'text/csv;charset=utf-8;' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'customer_database.csv'; a.click(); URL.revokeObjectURL(url) }

